dict(id="umpire", title="The interview loop (UMPIRE)", cat="Career", lvl=1,
 aka=["The interview loop (UMPIRE)", "UMPIRE", "DSA interview (45–60 min)", "Read + restate (2 min)", "Brute force first (3 min)", "Dry run (3 min)"],
 why="A fixed routine for every DSA interview so nerves don't decide your structure.",
 core=["Understand: restate the problem, ask about input size, ranges, duplicates, empty input; agree on 2 examples. Match: name the pattern. Plan: describe the approach in words and give its complexity; get a nod. Implement: clean code, good names. Review: dry-run an example and an edge case. Evaluate: complexity, trade-offs, what you'd improve.",
       "Always say the brute force first. It shows you can solve it, gives you a fallback and often reveals the optimisation."],
 points=["Spend ~5 min understanding, ~5 planning, ~20 coding, ~5 testing in a 45-min round", "If stuck, think aloud about what you know; interviewers give hints to people who talk"],
 pit=["Coding before the interviewer agrees with the approach"],
 ask=[], learn=[("CodePath UMPIRE guide", "https://guides.codepath.org/compsci/UMPIRE-Interview-Strategy")], rel=["speak-aloud", "pattern-thinking", "mock-interviews"]),

