dict(id="referrals", title="Referrals and LinkedIn outreach", cat="Career", lvl=1,
 aka=["Referrals", "Referral message (LinkedIn, 300 chars)", "referral", "40 referral asks"],
 why="The strongest off-campus channel: the Eternal (Zomato) story in this guide came through a referral.",
 core=["Find employees or alumni at the target company on LinkedIn (search 'company + RAIT' first, then any engineer). Send a short, specific note with the job ID and your resume link. Ask for a referral, not 'a job'.",
       "Make it easy to say yes: one-line intro, two proofs (problems solved, project), the exact role and job ID, a resume link. Thank them either way and follow up once after 5–7 days.",
       "Build the network before you need it: comment thoughtfully on engineers' posts, share your project write-ups."],
 code="Hi [Name], I'm a 3rd-year CSE (Cybersecurity) student; I've solved 450+ DSA problems and built [project in one line].\nI'm applying for [Role, Job ID] at [Company]. Would you be open to referring me?\nResume: [link]. Thank you!",
 points=["10 referral messages a week", "Alumni reply far more often than strangers", "Track every message in your sheet"],
 pit=["'Hi, any openings?' messages with no context", "Messaging the same person repeatedly"],
 ask=[], learn=[], rel=["application-pipeline", "resume", "cold-email"]),

