dict(id="offer", title="Offers, CTC and negotiation", cat="Career", lvl=2,
 aka=["Offer basics", "HR", "offer"],
 why="Freshers often lose money or sign bad bonds by not knowing what to ask.",
 core=["CTC (cost to company) includes fixed salary, variable/bonus, joining bonus, stock (RSUs vesting over years), benefits. In-hand monthly pay is fixed salary minus tax and PF, divided by 12. Ask for the breakdown in writing.",
       "Check the service agreement or bond clause, notice period, location and relocation support before signing.",
       "Negotiation: research ranges on levels.fyi and Glassdoor; avoid naming a number first; if you have a competing written offer, mention it politely. Mass-recruiter fresher offers are rarely negotiable; product companies sometimes adjust joining bonus."],
 points=["RSUs: 4-year vesting is common, often with a 1-year cliff", "PPO = pre-placement offer from an internship"],
 pit=["Comparing CTCs without separating fixed and variable"],
 ask=["What are your salary expectations?"],
 learn=[("levels.fyi", "https://www.levels.fyi"), ("Glassdoor India", "https://www.glassdoor.co.in")], rel=["application-pipeline"]),

